// OperatorNameContainsFold applies the ContainsFold predicate on the "operator_name" field.
func OperatorNameContainsFold(v string) predicate.GameServerBackup {
	return predicate.GameServerBackup(sql.FieldContainsFold(FieldOperatorName, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GameServerBackup) predicate.GameServerBackup {
	return predicate.GameServerBackup(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GameServerBackup) predicate.GameServerBackup {
	return predicate.GameServerBackup(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GameServerBackup) predicate.GameServerBackup {
	return predicate.GameServerBackup(sql.NotPredicates(p))
}
